    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum PltAntiIceValue {
        Select1,
        Select2,
        Select3,
    }
    pub type PltAntiIceValueCallback<'a> = &'a mut dyn FnMut(PltAntiIceValue);
    impl core::convert::TryFrom<u16> for PltAntiIceValue {
        type Error = u16;

        fn try_from(value: u16) -> Result<Self, Self::Error> {
            match value {
                0 => Ok(Self::Select1),
                1 => Ok(Self::Select2),
                2 => Ok(Self::Select3),
                value => Err(value),
            }
        }
    }

    /// PILOT Engine/Probe Anti-Ice
    /// Input: switch to previous or next state
    /// Input: set position
    /// Output: selector position
    pub struct PltAntiIce(Selector<4624, 24576, 13>);
    impl PltAntiIce {
        pub const fn new() -> Self {
            Self(Selector::new())
        }
        pub const fn value(&self) -> u16 {
            self.0.value()
        }
    }
    impl Default for PltAntiIce {
        fn default() -> Self {
            Self::new()
        }
    }
    impl Control for PltAntiIce {
        fn accept(&mut self, packet: Packet<'_>) {
            self.0.accept(packet);
        }
        fn commit(&mut self) -> bool {
            self.0.commit()
        }
    }

